export default {
  async fetch(request, env, ctx) {
    const { prompt } = await request.json();
    // CPU-ms bills only while this isolate executes.
    const upstream = await fetch('https://api.example.com/v1/chat', {
      method: 'POST',
      body: JSON.stringify({ prompt }),
      headers: { 'content-type': 'application/json' },
    });
    // Here it breaks: no Node APIs by default. Anything importing fs, net or
    // a native addon needs nodejs_compat, and some libraries never port.
    return new Response(upstream.body, { headers: { 'content-type': 'text/event-stream' } });
  },
};

